import type {RefObject} from 'react';
import {useEffect, useState} from 'react';

import type {PopupPlacement} from '@gravity-ui/uikit';
import debounce from 'lodash/debounce';

const minDistanceToScreen = 10;

export function usePopupHeight(
    anchorRef?: RefObject<HTMLElement | Element>,
    placement?: PopupPlacement,
): number {
    const [popupHeight, setPopupHeight] = useState(0);

    useEffect(() => {
        const bottomPlacement = new Set<PopupPlacement>(['bottom', 'bottom-start', 'bottom-end']);

        if (
            !placement ||
            (Array.isArray(placement) ? placement : [placement]).some(
                (item) => !bottomPlacement.has(item),
            )
        ) {
            return;
        }

        const calculatePopupHeight = debounce(() => {
            const anchorElement = anchorRef?.current;

            if (!anchorElement) {
                return;
            }

            const {bottom} = anchorElement.getBoundingClientRect();

            setPopupHeight(window.innerHeight - bottom - minDistanceToScreen);
        }, 100);

        calculatePopupHeight();
        window.addEventListener('resize', calculatePopupHeight);
        window.addEventListener('scroll', calculatePopupHeight);

        // eslint-disable-next-line consistent-return
        return () => {
            window.removeEventListener('resize', calculatePopupHeight);
            window.removeEventListener('scroll', calculatePopupHeight);
        };
    }, [anchorRef, placement]);

    return popupHeight;
}
